#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Text;
using NUnit.Framework;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;

public sealed class WifeAppearanceIntegrationTests
{
    const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
    static Type Sports(string name)=>Type.GetType("LWS.TruckSports."+name+", Assembly-CSharp",true);
    static object Get(object owner,string name)=>owner.GetType().GetField(name,Any) is FieldInfo field?field.GetValue(owner):owner.GetType().GetProperty(name,Any).GetValue(owner);
    static void Set(object owner,string name,object value){if(owner.GetType().GetField(name,Any) is FieldInfo field)field.SetValue(owner,value);else owner.GetType().GetProperty(name,Any).SetValue(owner,value);}
    static object Call(object owner,string name,params object[] args)=>owner.GetType().GetMethods(Any).Single(method=>method.Name==name&&method.GetParameters().Length==args.Length).Invoke(owner,args);
    static object Registry(string name,params object[] args)=>Sports("SportsParticipantRegistry").GetMethod(name).Invoke(null,args);
    Component match;object[] pairs,hosts;Component[] trucks;string[] ids;IDisposable lease;GameObject isolation;
    [TearDown]public void Cleanup(){Time.timeScale=1;if(match!=null)Call(match,"SetupScreen");if(isolation!=null)UnityEngine.Object.DestroyImmediate(isolation);Registry("ForgetCache");lease?.Dispose();lease=null;}
    IEnumerator LoadOriginal()
    {
        lease=(IDisposable)Sports("SportsPrefs").GetMethod("IsolateValidation").Invoke(null,new object[]{"WifeAppearance"+Guid.NewGuid().ToString("N")});Registry("ForgetCache");isolation=new GameObject("Explicit Wife appearance physical-role fixture");UnityEngine.Object.DontDestroyOnLoad(isolation);isolation.AddComponent(Sports("SportsProbeInputIsolation"));EditorSceneManager.LoadSceneInPlayMode("Assets/TruckWifeCarrying/Scenes/TruckWifeCarrying.unity",new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;match=(Component)UnityEngine.Object.FindAnyObjectByType(Type.GetType("LWS.TruckWifeCarrying.WifeMatch, Assembly-CSharp",true));Assert.That(match,Is.Not.Null);Call(match,"AllBots");Set(match,"option",0);pairs=((Array)Get(match,"pairs")).Cast<object>().ToArray();trucks=pairs.Select(pair=>(Component)Get(pair,"driver")).Concat(pairs.Select(pair=>(Component)Get(pair,"passenger"))).ToArray();hosts=((Array)Get(match,"appearanceHosts")).Cast<object>().ToArray();Assert.That(hosts.Length,Is.EqualTo(8),"Invoke BindMissingWifeRoleHosts first.");ids=new string[8];
        for(int i=0;i<8;i++){Assert.That(Get(trucks[i],"appearanceHost"),Is.SameAs(hosts[i]));Assert.That(Get(hosts[i],"participantSlot"),Is.EqualTo(i));ids[i]=(string)Get(Registry("Create","Same Pair Driver"),"id");Registry("UseInSeat",i,ids[i]);Save(ids[i],i<4?"truck.fire":"novelty.icecream");}Call(match,"RefreshParticipants",false);
        var originalParts=Physical().Keys.ToArray();var bindings=(Array)Get(match,"appearanceHosts");Set(match,"appearanceHosts",Array.CreateInstance(Sports("SportsTruckAppearanceHost"),0));foreach(var truck in trucks)Set(truck,"appearanceHost",null);
        try{Assert.That(Call(match,"StartMatch"),Is.EqualTo(true));double deadline=Time.realtimeSinceStartupAsDouble+8;while(Get(match,"Phase").ToString()=="Countdown"&&Time.realtimeSinceStartupAsDouble<deadline)yield return null;Assert.That(Get(match,"Phase").ToString(),Is.EqualTo("Race"));yield return null;yield return null;((Behaviour)match).enabled=false;foreach(var pair in pairs)Call(pair,"Stop");}
        finally{Set(match,"appearanceHosts",bindings);for(int i=0;i<8;i++)Set(trucks[i],"appearanceHost",hosts[i]);}
        var initialized=Physical();foreach(var component in originalParts)Assert.That(initialized.ContainsKey(component),Is.True,"Original component lost during original no-appearance startup.");var allowed=new HashSet<Collider>();foreach(var truck in trucks)foreach(var wheel in (Array)Get(truck,"wheels")){var collider=(Collider)Get(Get(wheel,"wheel"),"meshCollider");if(collider!=null)allowed.Add(collider);}foreach(var added in initialized.Keys.Except(originalParts))Assert.That(added is Collider collider&&allowed.Contains(collider),Is.True,"Only original NWH wheel initialization may add physical components.");
    }
    static void Save(string id,string body){var draft=Registry("GetAppearance",id);Set(draft,"bodyId",body);((IList)Get(draft,"selections")).Clear();Registry("TrySetAppearance",id,draft);Registry("ForgetCache");Assert.That(Get(Registry("GetAppearance",id),"bodyId"),Is.EqualTo(body));}
    static string Config(Component component){if(component is Rigidbody body)return body.mass+":"+body.centerOfMass.ToString("R")+":"+body.inertiaTensor.ToString("R")+":"+body.linearDamping+":"+body.angularDamping;var shape=(Collider)component;string text=shape.isTrigger+":"+(shape.sharedMaterial!=null?shape.sharedMaterial.GetInstanceID():0);if(shape is BoxCollider box)text+=":"+box.center.ToString("R")+":"+box.size.ToString("R");if(shape is MeshCollider mesh)text+=":"+(mesh.sharedMesh!=null?mesh.sharedMesh.GetInstanceID():0);return text;}
    Dictionary<Component,string> Physical()=>trucks.SelectMany(truck=>truck.GetComponentsInChildren<Component>(true)).Where(component=>component is Rigidbody||component is Collider).Distinct().ToDictionary(component=>component,Config);
    void SamePhysical(Dictionary<Component,string> before){var now=Physical();CollectionAssert.AreEquivalent(before.Keys,now.Keys);foreach(var pair in before)Assert.That(now[pair.Key],Is.EqualTo(pair.Value),"Original initialized physical configuration changed: "+pair.Key.name);}
    string Wheels(){var text=new StringBuilder();foreach(var truck in trucks)foreach(var wheel in (Array)Get(truck,"wheels")){var data=Get(wheel,"wheel");var spring=Get(wheel,"spring");text.Append(((Component)wheel).GetInstanceID()).Append(':').Append(Get(data,"radius")).Append(':').Append(Get(data,"width")).Append(':').Append(Get(spring,"maxForce")).Append(':').Append(Get(spring,"maxLength"));}return text.ToString();}
    string Gear(){var text=new StringBuilder();foreach(var pair in pairs){var cradle=(Transform)Get(pair,"cradle");text.Append(cradle.GetInstanceID()).Append(':').Append(cradle.parent.GetInstanceID()).Append(':').Append(cradle.localPosition.ToString("R")).Append(':').Append(cradle.localRotation.ToString("R")).Append(':').Append(cradle.localScale.ToString("R")).Append(':').Append(((Vector3)Get(pair,"roofAnchor")).ToString("R"));foreach(var line in (Array)Get(pair,"straps"))text.Append(':').Append(((Component)line).GetInstanceID());}return text.ToString();}
    void AssertOwners(bool swapped)
    {
        for(int i=0;i<8;i++){int slot=(i+(swapped?4:0))%8;Assert.That(Get(trucks[i],"slot"),Is.EqualTo(slot));Assert.That(Get(hosts[i],"ProfileId"),Is.EqualTo(ids[slot]));Assert.That(((Transform)Get(hosts[i],"presentationParent")),Is.SameAs(Get(trucks[i],"visuals")));Assert.That(trucks[i].transform.localScale,Is.EqualTo(Vector3.one*(i<4?1:.55f)));var model=(Transform)Get(hosts[i],"AppearanceRoot");Assert.That(model,Is.Not.Null);Assert.That(model.GetComponentsInChildren<Rigidbody>(true),Is.Empty);Assert.That(model.GetComponentsInChildren<Collider>(true),Is.Empty);if(i>=4){Assert.That(((Array)Get(hosts[i],"wheels")),Is.Empty);Assert.That(((Array)Get(hosts[i],"staticWheelPoses")).Length,Is.EqualTo(4));foreach(var wheel in (Array)Get(trucks[i],"wheels"))Assert.That(((Behaviour)wheel).enabled,Is.False);Assert.That(((AudioSource)Get(trucks[i],"engine")).enabled,Is.False);}}
    }
    [UnityTest,Timeout(180000)]public IEnumerator AllSevenDriverAndSmallerPassengerBodiesRetainActualCradlePhysicsAndScaleAwareWheelCenters()
    {
        yield return LoadOriginal();var physical=Physical();string wheels=Wheels(),gear=Gear();var views=Get(match,"views");var cameras=((Array)Get(views,"views")).Cast<object>().ToArray();var drivers=((Array)Get(views,"trucks")).Cast<object>().ToArray();
        foreach(string body in new[]{"truck.fire","truck.monster","truck.lifted","semi.lowrider","novelty.hotdog","novelty.icecream","semi.standard"})
        {
            Save(ids[0],body);Save(ids[4],body);Call(match,"RefreshParticipants",false);Call(match,"BeginRace");AssertOwners(false);Assert.That(Get(hosts[0],"EffectiveBodyId"),Is.EqualTo(body));Assert.That(Get(hosts[4],"EffectiveBodyId"),Is.EqualTo(body));SamePhysical(physical);Assert.That(Wheels(),Is.EqualTo(wheels));Assert.That(Gear(),Is.EqualTo(gear));CollectionAssert.AreEqual(drivers,((Array)Get(views,"trucks")).Cast<object>());CollectionAssert.AreEqual(cameras,((Array)Get(views,"views")).Cast<object>());
            var poses=((Array)Get(hosts[4],"staticWheelPoses")).Cast<object>().ToArray();var fits=((Array)Get(hosts[4],"compatibleBodies")).Cast<object>().Single(fit=>(string)Get(fit,"bodyId")==body);foreach(var wheel in ((IEnumerable)Get(hosts[4],"wheelVisuals")).Cast<object>()){var source=(Transform)Get(wheel,"source");int index=Array.FindIndex(poses,pose=>(Transform)Get(pose,"source")==source);Assert.That(index,Is.GreaterThanOrEqualTo(0));var group=((Array)Get(fits,"wheelGeometry")).Cast<object>().Single(entry=>(int)Get(entry,"physicalWheel")==index);float expected=((float)Get(group,"visualDiameter")-(float)Get(poses[index],"diameter"))*.55f*.5f;Assert.That((float)Get(wheel,"verticalOffset"),Is.EqualTo(expected).Within(1e-6));Call(hosts[4],"LateUpdate");Assert.That(Vector3.Distance(((Transform)Get(wheel,"visual")).position,source.TransformPoint((Vector3)Get(poses[index],"center"))+trucks[4].transform.up*expected),Is.LessThan(2e-5));}
        }
        int[] revisions=hosts.Select(host=>(int)Get(host,"AppearanceRevision")).ToArray();Call(match,"SetupScreen");Assert.That(Call(match,"StartMatch"),Is.EqualTo(true));CollectionAssert.AreEqual(revisions,hosts.Select(host=>(int)Get(host,"AppearanceRevision")));SamePhysical(physical);TestContext.WriteLine("WIFE_APPEARANCE original actual countdown/NWH initialization; all7 real bodies on powered driver and .55 nonpowered passenger, exact initialized physical/gear/scale/controller/camera refs, real static source centers/scale-aware wheel offsets, duplicate-name IDs/rematch. Controlled samples, no race/art/hardware acceptance claim.");
    }
    [UnityTest,Timeout(180000)]public IEnumerator ActualRoleSwapAndInactivePairVisibilityKeepIndependentProfilesAndOriginalPhysicalCarryJoint()
    {
        yield return LoadOriginal();Call(match,"BeginRace");AssertOwners(false);var physical=Physical();string wheels=Wheels(),gear=Gear();var identities=ids.Select(id=>Registry("GetAppearance",id)).Select(JsonUtility.ToJson).ToArray();Set(match,"Phase",Enum.Parse(Get(match,"Phase").GetType(),"RaceResult"));Call(match,"ExtraAction","swaproles");Assert.That(Get(match,"Swapped"),Is.EqualTo(true));Call(match,"BeginRace");AssertOwners(true);SamePhysical(physical);Assert.That(Wheels(),Is.EqualTo(wheels));Assert.That(Gear(),Is.EqualTo(gear));for(int i=0;i<8;i++)Assert.That(JsonUtility.ToJson(Registry("GetAppearance",ids[i])),Is.EqualTo(identities[i]));
        Call(pairs[0],"Prepare",false);Assert.That(Get(pairs[0],"State").ToString(),Is.EqualTo("Inactive"));Assert.That(((Transform)Get(pairs[0],"cradle")).gameObject.activeSelf,Is.False);foreach(int i in new[]{0,4})Assert.That(((Transform)Get(hosts[i],"AppearanceRoot")).GetComponentsInChildren<Renderer>(true).All(renderer=>!renderer.gameObject.activeInHierarchy),Is.True,"Original inner-visual inactivity must also hide selected body/accessories.");Call(pairs[0],"Prepare",true);Call(pairs[0],"Release");Assert.That(Get(pairs[0],"Carried"),Is.EqualTo(true));var joint=(ConfigurableJoint)Get(pairs[0],"joint");Assert.That(joint.connectedBody,Is.SameAs(Get(trucks[0],"body")));Assert.That(joint.connectedAnchor,Is.EqualTo(Get(pairs[0],"roofAnchor")));Assert.That(joint.slerpDrive.positionSpring,Is.EqualTo(11));Assert.That(joint.slerpDrive.positionDamper,Is.EqualTo(3));Assert.That(joint.slerpDrive.maximumForce,Is.EqualTo(20));Assert.That(joint.xMotion,Is.EqualTo(ConfigurableJointMotion.Locked));Assert.That(joint.angularXMotion,Is.EqualTo(ConfigurableJointMotion.Limited));Call(pairs[0],"Stop");Assert.That(Call(pairs[0],"Drop","controlled native appearance fixture"),Is.EqualTo(true));Assert.That(Get(pairs[0],"Carried"),Is.EqualTo(false));Assert.That(Get(hosts[0],"ProfileId"),Is.EqualTo(ids[4]));Assert.That(Get(hosts[4],"ProfileId"),Is.EqualTo(ids[0]));Assert.That(Wheels(),Is.EqualTo(wheels));Assert.That(Gear(),Is.EqualTo(gear));TestContext.WriteLine("WIFE_ROLE_APPEARANCE source ExtraAction role swap, actual paired Prepare/Release/Drop and .55 hidden-inactive presentation retain independent profile IDs, original physical joint limits/drive/roof anchors and disabled passenger NWH. Existing rules drive transitions; explicit controlled fixture, no full-race claim.");
    }
}
